func zzSchemeWithHeaders(t *testing.T, tlsOn bool, hdr map[string]string) string {
	t.Helper()
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	for k, v := range hdr {
		req.Header.Set(k, v)
	}
	if tlsOn {
		req.TLS = &tls.ConnectionState{}
	}
	c := NewContext(req, nil, nil)
	return c.Scheme()
}

func TestZZProbe(t *testing.T) {
	cases := []struct {
		name string
		tls  bool
		hdr  map[string]string
		want string
	}{
		{"no headers", false, nil, "http"},
		{"TLS", true, nil, "https"},
		{"XFP https", false, map[string]string{HeaderXForwardedProto: "https"}, "https"},
		{"XFP http", false, map[string]string{HeaderXForwardedProto: "http"}, "http"},
		{"XFP ftp (invalid)", false, map[string]string{HeaderXForwardedProto: "ftp"}, "http"},
		{"XFP ftp + XFProtocol https", false, map[string]string{HeaderXForwardedProto: "ftp", HeaderXForwardedProtocol: "https"}, "https"},
		{"all garbage", false, map[string]string{HeaderXForwardedProto: "garbage", HeaderXForwardedProtocol: "garbage", HeaderXForwardedSsl: "on", HeaderXUrlScheme: "garbage"}, "http"},
		{"XFP garbage + XFProtocol https", false, map[string]string{HeaderXForwardedProto: "garbage", HeaderXForwardedProtocol: "https"}, "https"},
		{"XForwardedSsl on", false, map[string]string{HeaderXForwardedSsl: "on"}, "https"},
		{"XUrlScheme https", false, map[string]string{HeaderXUrlScheme: "https"}, "https"},
		{"XFProtocol gopher", false, map[string]string{HeaderXForwardedProtocol: "gopher"}, "http"},
		{"XUrlScheme gopher", false, map[string]string{HeaderXUrlScheme: "gopher"}, "http"},
		{"XForwardedSsl off", false, map[string]string{HeaderXForwardedSsl: "off"}, "http"},
		{"XFP ftp + XForwardedSsl on", false, map[string]string{HeaderXForwardedProto: "ftp", HeaderXForwardedSsl: "on"}, "https"},
	}
	for _, tc := range cases {
		got := zzSchemeWithHeaders(t, tc.tls, tc.hdr)
