	req.Header.Set(HeaderXForwardedProto, "garbage")
	req.Header.Set(HeaderXForwardedProtocol, "garbage")
	req.Header.Set(HeaderXForwardedSsl, "off")
	req.Header.Set(HeaderXUrlScheme, "garbage")
	c := &context{request: req}
	if got := c.Scheme(); got != "http" {
		t.Errorf("ssl=off variant: want http got %q", got)
	} else {
		t.Logf("ssl=off variant: got %q (OK)", got)
