	req2 := httptest.NewRequest(http.MethodGet, "/", nil)
	req2.TLS = &tls.ConnectionState{}
	req2.Header.Set(HeaderXForwardedProto, "ftp")
	c2 := &context{request: req2}
	if got := c2.Scheme(); got != "https" {
		t.Errorf("TLS+garbage: want https got %q", got)
	}
}
