	return strings.Split(p, "/")
}

// patternMatches implements echo's documented route matching semantics:
// static segment == segment, :param matches exactly one segment, * matches rest (0+ segments)
func patternMatches(pattern, path string) bool {
	pp := segs(pattern)
	sp := segs(path)
	i := 0
	for ; i < len(pp); i++ {
		if pp[i] == "*" {
			return true
		}
		if i >= len(sp) {
			return false
		}
		if strings.HasPrefix(pp[i], ":") {
			if sp[i] == "" {
				return false
			}
			continue
		}
		if pp[i] != sp[i] {
			return false
		}
	}
	return len(pp) == len(sp)
}

